use std::collections::{VecDeque,HashSet};struct SnakeGame{w:i32,h:i32,food:Vec<Vec<i32>>,score:usize,b:VecDeque<i32>,s:HashSet<i32>}impl SnakeGame{fn new(w:i32,h:i32,food:Vec<Vec<i32>>)->Self{Self{w,h,food,score:0,b:VecDeque::from([0]),s:HashSet::from([0])}}fn make_move(&mut self,d:String)->i32{let p=*self.b.front().unwrap();let(mut r,mut c)=(p/self.w,p%self.w);match d.as_str(){"U"=>r-=1,"D"=>r+=1,"L"=>c-=1,_=>c+=1}if r<0||c<0||r>=self.h||c>=self.w{return -1}let id=r*self.w+c;let eat=self.score<self.food.len()&&self.food[self.score][0]==r&&self.food[self.score][1]==c;if !eat{let t=self.b.pop_back().unwrap();self.s.remove(&t);}if self.s.contains(&id){return -1}self.b.push_front(id);self.s.insert(id);if eat{self.score+=1}self.score as i32}}
